func MakePalindrome(str string) string {
	if len(str) == 0 {
		return ""
	}

	beginningOfSuffix := 0
	for !isPalindrome(str[beginningOfSuffix:]) {
		beginningOfSuffix++
	}

	prefix := str[:beginningOfSuffix]
	reversed := make([]byte, len(prefix))
	for i := range prefix {
		reversed[len(prefix)-1-i] = prefix[i]
	}

	return str + string(reversed)
