	ops := append([]string(nil), operator...)
	nums := append([]int(nil), operand...)

	for i := len(ops) - 1; i >= 0; i-- {
		if ops[i] == "**" {
			nums[i] = int(math.Floor(math.Pow(float64(nums[i]), float64(nums[i+1])) + 0.5))
			nums = append(nums[:i+1], nums[i+2:]...)
			ops = append(ops[:i], ops[i+1:]...)
		}
	}

	for i := 0; i < len(ops); i++ {
		if ops[i] == "*" {
			nums[i] *= nums[i+1]
			nums = append(nums[:i+1], nums[i+2:]...)
			ops = append(ops[:i], ops[i+1:]...)
			i--
		} else if ops[i] == "/" {
			nums[i] = int(math.Floor(float64(nums[i]) / float64(nums[i+1])))
			nums = append(nums[:i+1], nums[i+2:]...)
			ops = append(ops[:i], ops[i+1:]...)
			i--
		}
	}

	for i := 0; i < len(ops); i++ {
		if ops[i] == "+" {
			nums[i] += nums[i+1]
			nums = append(nums[:i+1], nums[i+2:]...)
			ops = append(ops[:i], ops[i+1:]...)
			i--
		} else if ops[i] == "-" {
			nums[i] -= nums[i+1]
			nums = append(nums[:i+1], nums[i+2:]...)
			ops = append(ops[:i], ops[i+1:]...)
			i--
		}
	}

	return nums[0]
}

